// ─────────────────────────────────────────────────────────────────────────────
// Grid Post
// ─────────────────────────────────────────────────────────────────────────────

const GridPost = ({item, index}) => {
  const [liked, setLiked] = useState(false);

  return (
    <TouchableOpacity
      activeOpacity={0.88}
      onPress={() => setLiked(current => !current)}
      style={styles.gridItem}>
      <Image source={{uri: item.image}} style={styles.gridImage} />

      <View style={styles.gridShade} />

      <View style={styles.gridBottom}>
        <Text style={[styles.gridHeart, liked && styles.gridHeartLiked]}>
          {liked ? '♥' : '♡'}
        </Text>

        <Text style={styles.gridCount}>
          {formatCount(item.likes + (liked ? 1 : 0))}
        </Text>
      </View>

      {index === 0 ? (
        <View style={styles.pinnedBadge}>
          <Text style={styles.pinnedText}>PINNED</Text>
        </View>
      ) : null}
    </TouchableOpacity>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Saved Story
// ─────────────────────────────────────────────────────────────────────────────

const SavedStoryCard = ({item}) => {
  const [saved, setSaved] = useState(true);

  return (
    <TouchableOpacity activeOpacity={0.9} style={styles.savedCard}>
      <Image source={{uri: item.image}} style={styles.savedImage} />

      <View style={styles.savedBody}>
        <View style={styles.savedTopRow}>
          <View style={styles.savedCategory}>
            <Text style={styles.savedCategoryText}>{item.category}</Text>
          </View>

          <Text style={styles.savedTime}>{item.timeAgo}</Text>
        </View>

        <Text style={styles.savedTitle} numberOfLines={2}>
          {item.title}
        </Text>

        <View style={styles.savedBottomRow}>
          <View style={styles.savedAuthorRow}>
            <Image
              source={{uri: item.authorAvatar}}
              style={styles.savedAvatar}
            />

            <View style={styles.savedAuthorInfo}>
              <Text style={styles.savedAuthor} numberOfLines={1}>
                {item.author}
              </Text>

              <Text style={styles.savedReadTime}>{item.readTime}</Text>
            </View>
          </View>

          <TouchableOpacity
            activeOpacity={0.7}
            onPress={() => setSaved(current => !current)}
            style={[styles.savedBookmark, saved && styles.savedBookmarkActive]}>
            <Text
              style={[
                styles.savedBookmarkText,
                saved && styles.savedBookmarkTextActive,
              ]}>
              {saved ? '◆' : '◇'}
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </TouchableOpacity>
  );
};

