// ─────────────────────────────────────────────────────────────────────────────
// Main Profile
// ─────────────────────────────────────────────────────────────────────────────

const ProfileScreen = ({navigation}) => {
  const profile = USER_PROFILE;

  const [activeTab, setActiveTab] = useState(0);
  const [isFollowing, setIsFollowing] = useState(false);

  const scrollY = useRef(new Animated.Value(0)).current;

  const coverTranslateY = scrollY.interpolate({
    inputRange: [-100, 0, COVER_HEIGHT],
    outputRange: [-30, 0, 90],
    extrapolate: 'clamp',
  });

  const coverScale = scrollY.interpolate({
    inputRange: [-100, 0],
    outputRange: [1.35, 1],
    extrapolateRight: 'clamp',
  });

  const coverOpacity = scrollY.interpolate({
    inputRange: [0, COVER_HEIGHT * 0.85],
    outputRange: [1, 0.55],
    extrapolate: 'clamp',
  });

  const topTitleOpacity = scrollY.interpolate({
    inputRange: [150, 205],
    outputRange: [0, 1],
    extrapolate: 'clamp',
  });

  const renderTabContent = () => {
    if (activeTab === 0) {
      return (
        <View style={styles.postsSection}>
          <View style={styles.postsHeader}>
            <Text style={styles.postsHeaderTitle}>Recent posts</Text>

            <Text style={styles.postsCount}>{profile.posts} posts</Text>
          </View>

          <View style={styles.grid}>
            {profile.recentPosts.map((post, index) => (
              <GridPost key={post.id} item={post} index={index} />
            ))}
          </View>
        </View>
      );
    }

    if (activeTab === 1) {
      return (
        <View style={styles.savedSection}>
          <View style={styles.postsHeader}>
            <Text style={styles.postsHeaderTitle}>Saved stories</Text>

            <Text style={styles.postsCount}>
              {profile.savedPosts.length} saved
            </Text>
          </View>

          {profile.savedPosts.length === 0 ? (
            <EmptySaved />
          ) : (
            <View style={styles.savedList}>
              {profile.savedPosts.map(post => (
                <SavedStoryCard key={post.id} item={post} />
              ))}
            </View>
          )}
        </View>
      );
    }

    return (
      <View style={styles.aboutSection}>
        <View style={styles.aboutCard}>
          <Text style={styles.aboutHeading}>About</Text>

          <Text style={styles.aboutBio}>{profile.bio}</Text>

          <View style={styles.aboutDivider} />

          <AboutItem
            icon="⌖"
            label="Location"
            value={profile.location || 'Bengaluru, India'}
          />

          <AboutItem icon="◷" label="Member since" value={profile.joinDate} />

          <AboutItem
            icon="↗"
            label="Website"
            value={profile.website || 'blackcoffer.com'}
            accent
          />
        </View>

        <View style={styles.aboutCard}>
          <Text style={styles.aboutHeading}>Interests</Text>

          <Text style={styles.aboutDescription}>
            Topics Aarav follows and writes about.
          </Text>

          <View style={styles.aboutInterests}>
            {profile.interests.map(interest => (
              <InterestChip key={interest} label={interest} />
            ))}
          </View>
        </View>
      </View>
    );
  };

  return (
    <View style={styles.container}>
      <StatusBar
        translucent
        backgroundColor="transparent"
        barStyle="light-content"
      />

      {/* Floating top navigation */}

      <View style={styles.topNavigation}>
        <TouchableOpacity
          activeOpacity={0.75}
          onPress={() => {
            if (navigation?.canGoBack?.()) {
              navigation.goBack();
            }
          }}
          style={styles.navigationButton}>
          <BackIcon />
        </TouchableOpacity>

        <Animated.View
          pointerEvents="none"
          style={[styles.scrolledTitle, {opacity: topTitleOpacity}]}>
          <Image source={{uri: profile.avatar}} style={styles.scrolledAvatar} />

          <View>
            <Text style={styles.scrolledName}>{profile.name}</Text>

            <Text style={styles.scrolledUsername}>{profile.username}</Text>
          </View>
        </Animated.View>

        <TouchableOpacity activeOpacity={0.75} style={styles.navigationButton}>
          <MoreIcon />
        </TouchableOpacity>
      </View>

      <Animated.ScrollView
        showsVerticalScrollIndicator={false}
        scrollEventThrottle={16}
        contentContainerStyle={styles.scrollContent}
        onScroll={Animated.event(
          [
            {
              nativeEvent: {
                contentOffset: {
                  y: scrollY,
                },
              },
            },
          ],
          {
            useNativeDriver: true,
          },
        )}>
        {/* Cover */}

        <View style={styles.coverContainer}>
          <Animated.Image
            source={{uri: profile.coverPhoto}}
            style={[
              styles.coverImage,
              {
                opacity: coverOpacity,
                transform: [{translateY: coverTranslateY}, {scale: coverScale}],
              },
            ]}
          />

          <View style={styles.coverDarkLayer} />
          <View style={styles.coverBottomLayer} />

          <View style={styles.coverBrand}>
            <Text style={styles.coverBrandText}>BWStory Creator</Text>
          </View>
        </View>

        {/* Main profile body */}

        <View style={styles.profileBody}>
          {/* Avatar + share */}

          <View style={styles.avatarRow}>
            <View style={styles.avatarOuter}>
              <Image source={{uri: profile.avatar}} style={styles.avatar} />

              {profile.verified ? <VerifiedBadge /> : null}
            </View>

            <TouchableOpacity activeOpacity={0.75} style={styles.shareButton}>
              <ShareIcon />
            </TouchableOpacity>
          </View>

          {/* Identity */}

          <View style={styles.identitySection}>
            <View style={styles.nameRow}>
              <Text style={styles.displayName}>{profile.name}</Text>

              {profile.verified ? (
                <View style={styles.inlineVerified}>
                  <Text style={styles.inlineVerifiedText}>✓</Text>
                </View>
              ) : null}
            </View>

            <Text style={styles.username}>{profile.username}</Text>

            <Text style={styles.bio}>{profile.bio}</Text>
          </View>

          {/* Interests */}

          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.interestsRow}>
            {profile.interests.map(interest => (
              <InterestChip key={interest} label={interest} />
            ))}
          </ScrollView>

          {/* Stats */}

          <View style={styles.statsCard}>
            <StatItem value={profile.posts} label="Posts" />

            <View style={styles.statDivider} />

            <StatItem value={profile.followers} label="Followers" />

            <View style={styles.statDivider} />

            <StatItem value={profile.following} label="Following" />
          </View>

          {/* Actions */}

          <View style={styles.actionRow}>
            <TouchableOpacity
              activeOpacity={0.82}
              onPress={() => setIsFollowing(current => !current)}
              style={[
                styles.followButton,
                isFollowing && styles.followButtonFollowing,
              ]}>
              <Text
                style={[
                  styles.followButtonText,
                  isFollowing && styles.followButtonTextFollowing,
                ]}>
                {isFollowing ? '✓  Following' : '+  Follow'}
              </Text>
            </TouchableOpacity>

            <TouchableOpacity activeOpacity={0.8} style={styles.messageButton}>
              <Text style={styles.messageButtonText}>Message</Text>
            </TouchableOpacity>
          </View>

          {/* Tabs */}

          <View style={styles.tabs}>
            {TABS.map((tab, index) => {
              const active = activeTab === index;

              return (
                <TouchableOpacity
                  key={tab}
                  activeOpacity={0.75}
                  onPress={() => setActiveTab(index)}
                  style={styles.tab}>
                  <Text
                    style={[styles.tabText, active && styles.tabTextActive]}>
                    {tab}
                  </Text>

                  {active ? <View style={styles.tabIndicator} /> : null}
                </TouchableOpacity>
              );
            })}
          </View>
        </View>

        {/* Tab body */}

        {renderTabContent()}

        <View style={styles.bottomSpacing} />
      </Animated.ScrollView>
    </View>
  );
};

