// ─────────────────────────────────────────────────────────────────────────────
// Main Screen
// ─────────────────────────────────────────────────────────────────────────────

const DiscoverScreen = () => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [searchVisible, setSearchVisible] = useState(false);
  const [searchText, setSearchText] = useState('');

  const scrollY = useRef(new Animated.Value(0)).current;

  const filteredPosts = useMemo(() => {
    const query = searchText.trim().toLowerCase();

    return DISCOVER_POSTS.filter(post => {
      const matchesCategory =
        activeCategory === 'all' ||
        post.categoryId === activeCategory ||
        post.category.toLowerCase() === activeCategory;

      if (!matchesCategory) {
        return false;
      }

      if (!query) {
        return true;
      }

      const searchableText = [
        post.title,
        post.summary,
        post.category,
        post.author,
        post.authorUsername,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();

      return searchableText.includes(query);
    });
  }, [activeCategory, searchText]);

  const headerBorderOpacity = scrollY.interpolate({
    inputRange: [0, 35],
    outputRange: [0, 1],
    extrapolate: 'clamp',
  });

  const handleSearchToggle = () => {
    if (searchVisible) {
      setSearchText('');
    }

    setSearchVisible(current => !current);
  };

  return (
    <View style={styles.container}>
      <StatusBar barStyle="light-content" backgroundColor={COLORS.bg} />

      <View style={styles.fixedHeader}>
        <Header
          searchVisible={searchVisible}
          onSearchPress={handleSearchToggle}
        />

        {searchVisible ? (
          <SearchBar
            value={searchText}
            onChangeText={setSearchText}
            onClose={() => {
              setSearchText('');
              setSearchVisible(false);
            }}
          />
        ) : null}

        <Animated.View
          pointerEvents="none"
          style={[styles.headerBottomBorder, {opacity: headerBorderOpacity}]}
        />
      </View>

      <Animated.ScrollView
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={[
          styles.scrollContent,
          searchVisible && styles.scrollContentSearch,
        ]}
        onScroll={Animated.event(
          [
            {
              nativeEvent: {
                contentOffset: {
                  y: scrollY,
                },
              },
            },
          ],
          {
            useNativeDriver: true,
          },
        )}
        scrollEventThrottle={16}>
        {/* Discover introduction */}

        <View style={styles.intro}>
          <Text style={styles.introEyebrow}>DISCOVER</Text>

          <Text style={styles.introTitle}>
            Stories worth{'\n'}
            <Text style={styles.introTitleAccent}>knowing.</Text>
          </Text>

          <Text style={styles.introSubtitle}>
            Fresh ideas, technology and stories curated for you.
          </Text>
        </View>

        {/* Stories */}

        <SectionHeader title="Stories" />

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.storiesContent}>
          <AddStory />

          {STORIES.map(story => (
            <StoryBubble key={story.id} item={story} />
          ))}
        </ScrollView>

        {/* Categories */}

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.categoriesContent}>
          {CATEGORIES.map(category => (
            <CategoryPill
              key={category.id}
              item={category}
              active={activeCategory === category.id}
              onPress={() => setActiveCategory(category.id)}
            />
          ))}
        </ScrollView>

        {/* Feed */}

        <SectionHeader
          title={
            searchText
              ? 'Search results'
              : activeCategory === 'all'
              ? 'Trending'
              : CATEGORIES.find(category => category.id === activeCategory)
                  ?.label || 'Stories'
          }
          action={
            !searchText && activeCategory === 'all' ? 'See all  →' : undefined
          }
        />

        {filteredPosts.length > 0 ? (
          <View style={styles.feed}>
            {filteredPosts.map((post, index) => {
              const useHero =
                post.isLarge || (activeCategory !== 'all' && index === 0);

              return useHero ? (
                <HeroCard key={post.id} item={post} />
              ) : (
                <CompactCard key={post.id} item={post} />
              );
            })}
          </View>
        ) : (
          <EmptyState searching={searchText.length > 0} />
        )}

        <View style={styles.bottomSpace} />
      </Animated.ScrollView>
    </View>
  );
};

