// ─────────────────────────────────────────────────────────────────────────────
// Tab icon selector
// ─────────────────────────────────────────────────────────────────────────────

const TabIcon = ({name, active}) => {
  switch (name) {
    case 'Home':
      return <HomeIcon active={active} />;

    case 'Discover':
      return <DiscoverIcon active={active} />;

    case 'Saved':
      return <SavedIcon active={active} />;

    case 'Profile':
      return <ProfileIcon active={active} />;

    default:
      return null;
  }
};

