// ─────────────────────────────────────────────────────────────────────────────
// Custom Bottom Navigation
// ─────────────────────────────────────────────────────────────────────────────

const CustomTabBar = ({
  state,
  descriptors,
  navigation,
}) => {
  return (
    <View
      pointerEvents="box-none"
      style={styles.tabBarPosition}>

      <View style={styles.tabBarShadow}>
        <View style={styles.tabBar}>
          {state.routes.map((route, index) => {
            const isFocused = state.index === index;

            const {options} =
              descriptors[route.key];

            const onPress = () => {
              const event = navigation.emit({
                type: 'tabPress',
                target: route.key,
                canPreventDefault: true,
              });

              if (
                !isFocused &&
                !event.defaultPrevented
              ) {
                navigation.navigate(
                  route.name,
                  route.params,
                );
              }
            };

            const onLongPress = () => {
              navigation.emit({
                type: 'tabLongPress',
                target: route.key,
              });
            };

            if (route.name === 'Create') {
              return (
                <CreateTabButton
                  key={route.key}
                  onPress={onPress}
                  onLongPress={onLongPress}
                />
              );
            }

            return (
              <NormalTabButton
                key={route.key}
                route={route}
                active={isFocused}
                options={options}
                onPress={onPress}
                onLongPress={onLongPress}
              />
            );
          })}
        </View>
      </View>
    </View>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Navigation
// ─────────────────────────────────────────────────────────────────────────────

const AppNavigator = () => {
  return (
    <NavigationContainer>
      <Tab.Navigator
        initialRouteName="Discover"
        tabBar={props => (
          <CustomTabBar {...props} />
        )}
        screenOptions={{
          headerShown: false,
          lazy: true,
          sceneContainerStyle: {
            backgroundColor: COLORS.bg,
          },
        }}>

        <Tab.Screen
          name="Home"
          component={PlaceholderScreen}
        />

        <Tab.Screen
          name="Discover"
          component={DiscoverScreen}
        />

        <Tab.Screen
          name="Create"
          component={PlaceholderScreen}
        />

        <Tab.Screen
          name="Saved"
          component={PlaceholderScreen}
        />

        <Tab.Screen
          name="Profile"
          component={ProfileScreen}
        />
      </Tab.Navigator>
    </NavigationContainer>
  );
};

